-- GMP Terms Database Schema
-- Generated: 2026-05-22

DROP TABLE IF EXISTS gmp_terms;
DROP TABLE IF EXISTS gmp_synonyms;

CREATE TABLE gmp_terms (
    term_id       INTEGER PRIMARY KEY,
    canonical_term TEXT NOT NULL,
    term_type     TEXT NOT NULL,
    hypernym      TEXT,
    gmp_chapter   TEXT,
    created_at    INTEGER
);

CREATE TABLE gmp_synonyms (
    synonym_id    INTEGER PRIMARY KEY,
    term_id       INTEGER NOT NULL REFERENCES gmp_terms(term_id),
    synonym       TEXT NOT NULL,
    created_at    INTEGER
);

CREATE INDEX idx_gmp_terms_canonical ON gmp_terms(canonical_term);
CREATE INDEX idx_gmp_terms_type ON gmp_terms(term_type);
CREATE INDEX idx_gmp_synonyms_synonym ON gmp_synonyms(synonym);

